                    "sql": "DROP TABLE IF EXISTS public.Tuco_Kids_sku_master; CREATE TABLE public.Tuco_Kids_sku_master ( ean VARCHAR(50), name VARCHAR(100), commonsku VARCHAR(100), skucode VARCHAR(100), marketplace_sku VARCHAR(100), categorytype VARCHAR(100), set_of INT, gst_rate FLOAT, sub_category VARCHAR(100), category VARCHAR(100), gst_class VARCHAR(100), product_name VARCHAR(255), new_hsn_from_17_sept_25 VARCHAR(50), product_launch_date VARCHAR(50), product_image_url VARCHAR(500), brand VARCHAR(100), cogs FLOAT, tax_rule_name VARCHAR(100), product_type VARCHAR(100), mrp VARCHAR(50) ); drop table if exists public.Tuco_Kids_AMAZON_FACT_ITEMS_INTERMEDIATE; CREATE TABLE public.Tuco_Kids_AMAZON_FACT_ITEMS_INTERMEDIATE AS SELECT \"fulfillment-channel\" AS shop_name, cast(\"amazon-order-id\" as varchar) order_id, cast(\"amazon-order-id\" AS varchar) order_name, NULL AS customer_id, NULL AS phone, NULL AS tags, NULL AS line_item_id, cast(Sku as varchar) sku, ASIN AS product_id, cast(Currency as varchar) Currency, CASE WHEN \"order-status\" IN (\'Shipped - Returned to Seller\', \'Shipped - Returning to Seller\', \'Shipped - Rejected by Buyer\', \'Shipped - Damaged\') THEN 1 ELSE 0 END AS is_refund, coalesce(cast(UPPER(\"ship-city\") as varchar)) AS city, coalesce(cast(UPPER(\"ship-state\") as varchar)) AS state, cast(\"ship-postal-code\" as varchar) AS pincode, upper(cast(\"product-name\" as varchar)) AS product_name, NULL AS category, cast(\"order-status\" as varchar)order_status, TO_TIMESTAMP(\"purchase-date\", \'YYYY-MM-DDTHH:MI:SS+00:00\') AT TIME ZONE \'Asia/Kolkata\' AS order_timestamp, COALESCE(TRY_CAST(\"item-price\" AS double precision), 0) AS line_item_sales, COALESCE(TRY_CAST(\"shipping-price\" AS double precision), 0) AS shipping_price, COALESCE(TRY_CAST(quantity AS double precision), 0) AS quantity, COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) AS tax, COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) / NULLIF(COALESCE(TRY_CAST(\"item-tax\" 