, NULL AS landing_utm_channel, NULL AS referring_utm_channel, NULL AS final_utm_channel, NULL AS new_customer_flag, NULL AS acquisition_channel, NULL AS acquisition_product, COALESCE(TRY_CAST(\"shipping-tax\" AS double precision), 0) AS shipping_tax, COALESCE(TRY_CAST(\"ship-promotion-discount\" AS double precision), 0) AS ship_promotion_discount, COALESCE(TRY_CAST(\"gift-wrap-price\" AS double precision), 0) AS gift_wrap_price, COALESCE(TRY_CAST(\"gift-wrap-tax\" AS double precision), 0) AS gift_wrap_tax, cast(null as varchar) AS Email, cast(null as varchar) AS Name, cast(null as varchar) as Recipient_Name, case when \"amazon-order-id\" like \'S%\' then \'Stock Transfer\' else \'Sale Order\' end as Order_Type FROM ( SELECT *, \"purchase-date\" AS Purchase_datetime_PDT FROM public.Amazon_Tuco_Kids_get_flat_file_all_orders_data_by_last_update_general ) X; drop table if exists public.Tuco_Kids_AMAZON_FACT_ITEMS; CREATE TABLE public.Tuco_Kids_AMAZON_FACT_ITEMS AS SELECT fi.* ,COALESCE(UPPER(sm.product_name), UPPER(fi.product_name)) AS product_name_final ,COALESCE(UPPER(cast(sm.CATEGORY as varchar)), UPPER(cast(fi.category as varchar))) AS product_category ,UPPER(cast(null as varchar)) AS product_sub_category ,coalesce(sm.commonsku) as commonsku ,size ,color FROM public.Tuco_Kids_AMAZON_FACT_ITEMS_INTERMEDIATE fi left join (select * from (select product_name, color, size, marketplace_sku, marketplace_id, marketplace, commonsku, CATEGORY, ROW_NUMBER() OVER (PARTITION BY REPLACE(CAST(marketplace_sku AS VARCHAR), \' \', \'\') ORDER BY LENGTH(COALESCE(CAST(marketplace_sku AS VARCHAR), \'\')) DESC) AS rw FROM public.tuco_kids_final_sku_master where lower(marketplace) like \'%amazon%\' ) WHERE rw = 1 ) sm ON LOWER(REPLACE(CAST(fi.sku AS VARCHAR), \' \', \'\')) = LOWER(REPLACE(CAST(sm.marketplace_sku AS VARCHAR), \' \', \'\')) ;",
